#!/usr/bin/env python3
# Finvexa AI v6 — complete single-file application.
# Requires only Python 3.10+. No pip install, extracted folders, or API keys.
# Windows PowerShell: python .\Finvexa_AI.py
# Then open http://localhost:8066. Use --port 8001 if needed.
# Features: forecasts, order scenarios, editable ledger, filters, CSV export,
# cash status, due bills, summary totals, JSON backup/restore.
# Local browser storage; no connected AI, bank, account, or cloud database.
# Paid records are excluded; opening cash must be maintained by the user.

"""Exact decimal cash forecasts. No third-party dependencies."""
from datetime import date, timedelta
from decimal import Decimal, InvalidOperation

def money(value):
    try:
        n = Decimal(str(value))
        if not n.is_finite() or n < 0 or n > Decimal('1000000000000'):
            raise ValueError('Amount must be between zero and one trillion.')
        return n.quantize(Decimal('.01'))
    except InvalidOperation:
        raise ValueError('Invalid money amount.')

def forecast(data):
    start = date.fromisoformat(data['start'])
    days = int(data.get('days', 30))
    if not 1 <= days <= 366: raise ValueError('Forecast must cover 1–366 days.')
    cash, reserve = money(data['cash']), money(data.get('reserve', 0))
    events = {}
    for item in data.get('transactions', []):
        if item['kind'] not in ('income', 'expense'): raise ValueError('Invalid transaction type.')
        when = date.fromisoformat(item['date'])
        settled = money(item.get('settledAmount', 0))
        original = money(item['amount'])
        if settled > original: raise ValueError('Recorded payment cannot exceed the transaction amount.')
        if item.get('paid', False): continue
        item = {**item, 'amount': str(original-settled)}
        # Past unpaid items are overdue: count on the forecast start and flag the assumption.
        when = max(when, start)
        events.setdefault(when, []).append(item)
    rows = []
    for offset in range(days):
        day = start + timedelta(days=offset)
        income = sum((money(x['amount']) for x in events.get(day, []) if x['kind']=='income'), Decimal(0))
        expense = sum((money(x['amount']) for x in events.get(day, []) if x['kind']=='expense'), Decimal(0))
        opening = cash
        cash += income-expense
        rows.append(dict(date=day.isoformat(), opening=str(opening), income=str(income), expense=str(expense), balance=str(cash)))
    low = min(rows, key=lambda r: Decimal(r['balance']))
    shortage = next((r['date'] for r in rows if Decimal(r['balance']) < 0), None)
    below = next((r['date'] for r in rows if Decimal(r['balance']) < reserve), None)
    return dict(rows=rows, minimum=low['balance'], minimum_date=low['date'], shortage_date=shortage, below_reserve_date=below, ending=rows[-1]['balance'])

def analyze(data):
    base = forecast(data)
    order = data.get('order')
    scenarios = []
    if order:
        value, base_cost = money(order['value']), money(order['cost'])
        extras = sum((money(order.get(key, 0)) for key in ('packaging','delivery','fees','other')), Decimal(0))
        cost = base_cost + extras
        if cost > Decimal('1000000000000'): raise ValueError('Total order cost exceeds the supported limit.')
        cost_day, pay_day = date.fromisoformat(order['costDate']), date.fromisoformat(order['payDate'])
        start = date.fromisoformat(data['start'])
        if cost_day < start or pay_day < cost_day: raise ValueError('Order payment must be on or after its cost date, within the future.')
        advance = Decimal(str(order.get('advance', 0)))
        if not advance.is_finite() or not 0 <= advance <= 100: raise ValueError('Advance must be 0–100%.')
        delay_days = int(order.get('delayDays', 7))
        if not 0 <= delay_days <= 60: raise ValueError('Payment delay must be 0–60 days.')
        def order_forecast(pct, delay=0, projected_cost=cost):
            upfront=(value*pct/100).quantize(Decimal('.01'))
            transactions=data.get('transactions', []) + [dict(kind='expense',amount=str(projected_cost),date=cost_day.isoformat()),dict(kind='income',amount=str(upfront),date=cost_day.isoformat()),dict(kind='income',amount=str(value-upfront),date=(pay_day+timedelta(days=delay)).isoformat())]
            return forecast({**data,'transactions':transactions})
        for name, pct, delay, projected_cost in [('Your terms', advance, 0, cost), ('30% advance', Decimal(30), 0, cost), ('50% advance', Decimal(50), 0, cost), (f'Payment {delay_days} days late', advance, delay_days, cost), ('Costs rise by 10%', advance, 0, (cost*Decimal('1.10')).quantize(Decimal('.01')))]:
            result=order_forecast(pct, delay, projected_cost)
            scenarios.append(dict(name=name,advance=str(pct),cost=str(projected_cost),**result))
        reserve=money(data.get('reserve',0))
        # Daily balances increase monotonically with advance until full payment.
        # Binary search finds the lowest whole percentage meeting the reserve.
        horizon_end=start+timedelta(days=int(data.get('days',30))-1)
        recommendation=dict(percent=None, amount=None, reserve=str(reserve), status='unavailable')
        if cost_day > horizon_end:
            recommendation['reason']='The order starts outside this forecast. Extend the forecast period before checking an advance.'
        elif Decimal(order_forecast(Decimal(100))['minimum']) < reserve:
            recommendation['reason']='Even a 100% advance cannot maintain your reserve across this forecast. Review existing bills, order costs, or other funding.'
        else:
            low,high=0,100
            while low < high:
                middle=(low+high)//2
                if Decimal(order_forecast(Decimal(middle))['minimum']) >= reserve: high=middle
                else: low=middle+1
            recommendation.update(percent=low,amount=str((value*Decimal(low)/100).quantize(Decimal('.01'))),status='available',reason='Lowest whole advance percentage that maintains your reserve within the selected forecast, assuming on-time payment and unchanged costs.')
    chosen=scenarios[0] if scenarios else base
    gap=max(Decimal(0),-Decimal(chosen['minimum']))
    explanation=(f"The lowest projected balance is ₹{chosen['minimum']} on {chosen['minimum_date']}. "+(f"You need ₹{gap} more to avoid a negative balance. Compare advance payments before committing." if gap else 'The balance stays above zero under these payment assumptions.')+' This is a scheduled projection, not a guarantee. Overdue unpaid items are assumed to settle today; paid items are already included in opening cash.')
    summary = None
    if order:
        profit = value - cost
        margin = (profit / value * 100).quantize(Decimal('.01')) if value else None
        summary = dict(value=str(value), cost=str(cost),base_cost=str(base_cost),extra_costs=str(extras), profit=str(profit), margin_percent=str(margin) if margin is not None else None)
    return dict(baseline=base,scenarios=scenarios,explanation=explanation,order_summary=summary,advance_recommendation=recommendation if order else None)

