import json
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlsplit
import argparse

class FinvexaHandler(BaseHTTPRequestHandler):
    def respond(self, status, body, content_type):
        if isinstance(body, str): body=body.encode('utf-8')
        self.send_response(status)
        self.send_header('Content-Type',content_type)
        self.send_header('Content-Length',str(len(body)))
        self.send_header('Cache-Control','no-store')
        self.send_header('X-Content-Type-Options','nosniff')
        self.end_headers()
        self.wfile.write(body)
    def do_GET(self):
        path=urlsplit(self.path).path
        if path == '/favicon.ico': self.respond(204,b'','image/x-icon'); return
        if path not in ASSETS: self.respond(404,'Page not found','text/plain'); return
        mime,body=ASSETS[path]
        self.respond(200,body,mime)
    def do_POST(self):
        if urlsplit(self.path).path!='/api/analyze': self.respond(404,'{}','application/json'); return
        try:
            length=int(self.headers.get('Content-Length',0))
            if not 0 < length <= 1000000: raise ValueError('Request must be between 1 byte and 1 MB.')
            payload=json.loads(self.rfile.read(length))
            if not isinstance(payload,dict): raise ValueError('Expected a JSON object.')
            result=analyze(payload)
            self.respond(200,json.dumps(result),'application/json')
        except (ValueError,KeyError,TypeError,OverflowError,AttributeError) as exc:
            self.respond(400,json.dumps({'error':str(exc)}),'application/json')
    def log_message(self,format,*args):
        pass

def main():
    parser=argparse.ArgumentParser(description='Finvexa AI: a complete single-file cash-flow app')
    parser.add_argument('--port',type=int,default=8066,help='Local port, default 8066')
    args=parser.parse_args()
    if not 1 <= args.port <= 65535: parser.error('Port must be between 1 and 65535.')
    try:
        server=ThreadingHTTPServer(('127.0.0.1',args.port),FinvexaHandler)
    except OSError:
        print('This port is already in use. Stop the older server with Ctrl+C,')
        print('or run: python Finvexa_AI.py --port 8067')
        return
    print('\nFinvexa AI v6 - complete single-file application')
    print('Open in your browser: http://localhost:'+str(args.port))
    print('Keep this window open. Press Ctrl+C to stop.\n')
    try: server.serve_forever()
    except KeyboardInterrupt: print('\nFinvexa AI stopped.')
    finally: server.server_close()

if __name__=='__main__': main()
